                call = {**call, "function": {**function, "arguments": json.dumps(data, ensure_ascii=False)}}
                changed = True
        calls.append(call)
    slimmed = {key: value for key, value in message.items() if key not in (REASONING_KEY, REASONING_TOKENS_KEY)}
